		count, err = channelAnchorStorageObservation(t, h).CountEventNameStorage(context.Background(), "mailbox.card_decided")
		return err
	}(); err != nil || count != 1 {
		t.Fatalf("duplicate/restart changed chooser completion cardinality: %d %v", count, err)
	}
