					objectChannelIngress(t, callback, signing, id, fact)
					objectChannelIngress(t, callback, signing, id, fact)
					waitObjectChannelEffect(t, provider, "/v2/ack", func(input map[string]any) bool {
						return input["cursor"] == id
					})
				}
